import { SITE_NAME, absoluteUrl } from '@/lib/site'

// The share picture generated by app/opengraph-image.js. Named here because a page that sets its own
// openGraph would otherwise drop the file-based image.
const SHARE_IMAGE = { url: '/opengraph-image', width: 1200, height: 630 }

/**
 * Metadata for a public page, built the same way every time: a unique title and description, one
 * canonical address, and matching Open Graph and Twitter cards. `isIndexable` is false for pages that
 * are variations of another (a filtered or dated search): they point at the main page and ask search
 * engines not to index them, but still to follow their links. `image` is the share picture ({ url, width, height }):
 * a guide passes its cover; every other page uses the brand picture.
 */
export function pageMetadata({
  title,
  description,
  path,
  isIndexable = true,
  image = SHARE_IMAGE,
}) {
  const url = absoluteUrl(path)
  return {
    title,
    description,
    alternates: { canonical: url },
    robots: isIndexable ? { index: true, follow: true } : { index: false, follow: true },
    openGraph: {
      type: 'website',
      siteName: SITE_NAME,
      locale: 'en_KE',
      url,
      title,
      description,
      images: [image],
    },
    twitter: { card: 'summary_large_image', title, description, images: [image.url] },
  }
}
